        public static bool Attach(MapMarker m){if(!m.enemy||(m.sourceIndex!=69&&m.sourceIndex!=91))return false;if(m.GetComponent<PaperRegion2Encounter>()==null)m.gameObject.AddComponent<PaperRegion2Encounter>().Initialize(FindAnyObjectByType<WorldPrototype>(),m.sourceIndex);return true;}
        public void Initialize(WorldPrototype w,int index){world=w;data=Array.Find(Catalog.actors,a=>a.sourceIndex==index);knight=index==91;Health=data.health;serial=w.ResetSerial;room=Array.Find(w.Data.rooms,r=>r.r==2&&r.n==data.room);floor=-w.Data.enemies[index].floor;minX=room.x+data.bodyWidth*.5f+.1f;maxX=room.x+room.w-data.bodyWidth*.5f-.1f;var marker=w.Data.enemies[index];transform.localScale=Vector3.one;origin=new Vector3((marker.x+marker.w*.5f)/16,floor,0);transform.position=origin;visual=GetComponent<SpriteRenderer>();visual.color=Color.white;visual.sortingOrder=22;material=new Material(Resources.Load<Shader>("BossRegion1/BossPaper"));visual.sharedMaterial=material;frames=Frames(data);player=w.player.GetComponentInChildren<PaperSpritePlayer>();receiver=GetComponent<PaperAttackTarget>()??gameObject.AddComponent<PaperAttackTarget>();receiver.onHit.AddListener(Hit);zones=new[]{new BossDangerShape(null,Region2Presentation.Fx(3)),new BossDangerShape(null,Region2Presentation.Fx(4))};for(int i=0;i<10;i++)shots.Add(new Shot{shape=new BossDangerShape(null,Region2Presentation.Fx(0),24)});var go=new GameObject("Temporary crayon lance foothold");spear=go.AddComponent<SpriteRenderer>();spear.sprite=Region2Presentation.Fx(9);spear.sortingOrder=-2;spear.enabled=false;fires=new SpriteRenderer[2];for(int i=0;i<2;i++){var f=new GameObject("Arena wax brazier");fires[i]=f.AddComponent<SpriteRenderer>();fires[i].sortingOrder=-2;fires[i].sprite=Region2Presentation.DeviceFrame("brazier",0);f.transform.position=new Vector3(i==0?minX+.2f:maxX-.2f,floor+.45f,0);f.transform.localScale=Vector3.one*(.9f/fires[i].sprite.bounds.size.y);fires[i].enabled=false;}bagAt=4;if(w.Progression.DefeatedEncounters.Contains(index)){dead=rewarded=true;Health=0;clock=data.Clip("Death").Duration;receiver.enabled=false;}Render();}
        void Hit(){if(dead)return;if(!knight&&stagger<=0&&receiver.LastHitDirection.x*facing<0&&world.player.position.y<floor+data.bodyHeight*.8f){Region2Presentation.Burst(world,BodyBounds.center,"parry",facing);return;}Damage(1);}
        void Damage(int amount){if(dead)return;Health=Mathf.Max(0,Health-amount);if(Health>0)return;dead=true;EnemyRewardDrops.Emit(world,BodyBounds.center,knight?75:35);stagger=0;clock=0;Pattern=-1;receiver.enabled=false;world.Progression.DefeatedEncounters.Add(data.sourceIndex);Hide();ClearShots();ClearSpear();world.SetArenaHeat(room,false);foreach(var f in fires)f.enabled=false;Region2Presentation.Burst(world,BodyBounds.center,"death");GameAudio.Emit(SoundCue.Death,transform.position);}
        void Update(){Tick(Mathf.Min(Time.deltaTime,.05f));}
        public void Tick(float dt){if(world==null||zones==null||world.MapOpen)return;if(serial!=world.ResetSerial){serial=world.ResetSerial;if(!world.Progression.DefeatedEncounters.Contains(data.sourceIndex))ResetActor();}if(dt>1f/120){while(dt>1f/120){Tick(1f/120);dt-=1f/120;}if(dt>0)Tick(dt);return;}if(dead){clock+=dt;if(clock>=data.Clip("Death").Duration&&!rewarded){rewarded=true;world.Progression.Grant(data.reward);world.Progression.Say(knight?"부러져도 기사는 기사지. · 크레파스 벽타기 획득":"막기만 하면 갇혀. 튕겨내야 나아가. · 패링 획득",5);}Render();return;}
            var pp=world.player.position;bool inside=pp.x>=room.x&&pp.x<=room.x+room.w&&pp.y<=-room.y&&pp.y>=-(room.y+room.h+1);if(!inside||world.HazardInputBlocked){Engaged=false;Pattern=-1;clock=stagger=0;moving=false;Hide();ClearShots();Render();return;}Engaged=true;
            if(knight&&Health<=22&&!phase2){phase2=true;world.SetArenaHeat(room,true);foreach(var f in fires)f.enabled=true;world.Progression.Say("기사의 밀랍이 달아오릅니다. 발판에 오래 머물지 마세요.",3);}
            if(phase2)foreach(var f in fires)StructureFrameBlend.Device(f,"brazier",Time.time*7,3);
            TickShots(dt);if(spearLife>0){spearLife-=dt;if(spearLife<=0)ClearSpear();}if(stagger>0){clock+=dt;stagger=Mathf.Max(0,stagger-dt);if(stagger<=0){clock=0;pause=.15f;}Render();return;}
            if(Pattern<0){clock+=dt;pause-=dt;facing=pp.x>=transform.position.x?1:-1;moving=Mathf.Abs(pp.x-transform.position.x)>(knight?3.1f:2.6f);if(moving)Move(facing*(knight?1.4f:.7f)*dt);if(Mathf.Abs(pp.x-transform.position.x)>6.5f)pause=Mathf.Max(pause,.1f);else if(pause<=0)BeginPattern(Next());Render();return;}
            clock+=dt;Hide();if(knight)Knight(dt);else Turtle(dt);if(Pattern>=0&&clock>=data.Clip(StateName).Duration){last=Pattern;Pattern=-1;clock=0;pause=phase2?.12f:.18f;transform.position=new Vector3(transform.position.x,floor,0);Hide();}Render();
        }
        void Turtle(float dt){if(Pattern==0){bool active=clock>=.7f&&clock<1.2f;if(active&&!Move(facing*6.4f*dt)){Stagger(1);return;}if(clock<1.2f)Zone(0,(Vector2)transform.position+Vector2.up*.6f,new Vector2(1.15f,.65f),0,active,false,0);}else if(!emitted&&clock>=.85f){emitted=true;for(int i=0;i<3;i++){float a=(facing>0?35:145)+(i-1)*24;Launch((Vector2)transform.position+new Vector2(facing*.8f,.9f),new Vector2(Mathf.Cos(a*Mathf.Deg2Rad),Mathf.Sin(a*Mathf.Deg2Rad))*3.8f,9,false);}}}
        void Knight(float dt){switch(Pattern){case 0:for(int i=0;i<3;i++){float start=.55f+i*.35f,end=start+(i==2?.1f:.08f);if(clock<end){Zone(0,(Vector2)transform.position+new Vector2(facing*1.7f,1.1f),new Vector2(1.65f,.38f),0,clock>=start,false,i);break;}}break;
            case 1:if(clock<.65f)Zone(0,(Vector2)transform.position+new Vector2(facing*1.4f,1.2f),new Vector2(.7f,.2f),0,false,false,0);if(!emitted&&clock>=.65f){emitted=true;var from=(Vector2)transform.position+new Vector2(facing*1.25f,1.2f);Launch(from,new Vector2(aimX-from.x,floor+.75f-from.y).normalized*6.2f,0,true);}break;
            case 2:{bool active=clock>=.65f&&clock<1.15f;if(active&&!Move(facing*8*dt)){PlantSpear();Stagger(1);return;}if(clock<1.15f)Zone(0,(Vector2)transform.position+new Vector2(facing*.65f,.8f),new Vector2(1.15f,.78f),0,active,false,0);break;}
            case 3:if(clock>=.4f&&clock<.85f){float t=(clock-.4f)/.45f;transform.position=new Vector3(Mathf.Lerp(attackOrigin.x,aimX,t),floor+Mathf.Sin(t*Mathf.PI)*1.75f,0);}else if(clock>=.85f)transform.position=new Vector3(aimX,floor,0);if(clock<1.05f)Zone(1,new Vector2(aimX,floor+.25f),new Vector2(2.7f,.65f),0,clock>=.85f,true,0);if(!emitted&&clock>=.85f){emitted=true;Region2Presentation.Burst(world,new Vector2(aimX,floor+.1f),"slam");PaperVfx.Get()?.Dust(new Vector2(aimX,floor),1.6f);}break;}}
        void Zone(int i,Vector2 at,Vector2 radius,float angle,bool active,bool unblockable,int window){zones[i].Show(at,radius,angle,active);if(!active)return;if((impactMask&(1<<window))==0){impactMask|=1<<window;if(GetComponent<EnemyCombatVfx>()==null)Region2Presentation.Burst(world,at,knight?"knight":"turtle",facing);GameAudio.Emit(SoundCue.EnemyAttack,at,.7f);}if(!zones[i].Overlaps(PlayerBounds()))return;if(!unblockable&&world.Progression.Parrying){if((parryMask&(1<<window))==0){parryMask|=1<<window;world.Progression.ConfirmParry();Region2Presentation.Burst(world,at,"parry",-facing);if(Pattern!=0||!knight||parryMask==7)Stagger(knight?1.0f:1.1f);}return;}DamagePlayer(at,unblockable);}
