        public void BeginPattern(int value){if(dead||value<0||value>=(knight?4:2))return;Pattern=value;PatternMask|=1<<value;clock=stagger=0;emitted=moving=false;parryMask=impactMask=0;transform.position=new Vector3(transform.position.x,floor,0);attackOrigin=transform.position;facing=world.player.position.x>=transform.position.x?1:-1;aimX=Mathf.Clamp(world.player.position.x,Mathf.Max(minX,attackOrigin.x-5.5f),Mathf.Min(maxX,attackOrigin.x+5.5f));Hide();}
        int Next(){if(!knight)return last==0?1:0;if(bagAt>=4){for(int i=0;i<4;i++)bag[i]=i;for(int i=3;i>0;i--){int j=UnityEngine.Random.Range(0,i+1),swap=bag[i];bag[i]=bag[j];bag[j]=swap;}bagAt=0;}if(bag[bagAt]==last&&bagAt<3){int swap=bag[bagAt];bag[bagAt]=bag[bagAt+1];bag[bagAt+1]=swap;}return bag[bagAt++];}
