        void TickShots(float dt){foreach(var s in shots){if(s.life<=0)continue;s.life-=dt;s.position+=s.velocity*dt;s.velocity+=Vector2.down*s.gravity*dt;if(s.life<=0||GridMotor.Wall(world.Motor.Get(Mathf.FloorToInt(s.position.x),Mathf.FloorToInt(-s.position.y)))){s.life=0;s.shape.Hide();continue;}s.fxCooldown-=dt;if(s.fxCooldown<=0){s.fxCooldown=.055f;EnemyCombatEffects.Get(world)?.Projectile(s.position,s.velocity,knight?new Color(.75f,.4f,.47f):new Color(.76f,.62f,.32f),false);}
