        public IReadOnlyList<int> TemporaryPlatformCells=>spearCells;
        void PlantSpear(){ClearSpear();int row=Mathf.RoundToInt(-floor)-2,start=facing<0?room.x-1:room.x+room.w-1;for(int x=start;x<start+2;x++)if(world.Motor.Get(x,row)==0){int index=row*world.Data.width+x;world.Motor.cells[index]=4;spearCells.Add(index);}if(spearCells.Count==0)return;spear.transform.position=new Vector3(start+1,-row+.035f,0);spear.transform.localScale=new Vector3(2/spear.sprite.bounds.size.x,.12f/spear.sprite.bounds.size.y,1);spear.enabled=true;spearLife=6;}
