        void OnGUI(){if(!Engaged||dead)return;float scale=Mathf.Min(Screen.width/1920f,Screen.height/1080f);var old=GUI.matrix;GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float x=(Screen.width/scale-500)*.5f,y=Screen.height/scale-150;var style=new GUIStyle(GUI.skin.label){font=Resources.Load<Font>("UI/NotoSansCJKkr-Regular"),fontSize=20,alignment=TextAnchor.MiddleCenter};GUI.Label(new Rect(x,y-30,500,26),data.name,style);GUI.color=new Color(.11f,.1f,.09f,.9f);GUI.DrawTexture(new Rect(x,y,500,10),Texture2D.whiteTexture);GUI.color=knight?new Color(.65f,.38f,.4f):new Color(.67f,.57f,.33f);GUI.DrawTexture(new Rect(x,y,500*Health/data.health,10),Texture2D.whiteTexture);GUI.color=Color.white;GUI.matrix=old;}
        static void Dispose(UnityEngine.Object value){if(value==null)return;if(Application.isPlaying)Destroy(value);else DestroyImmediate(value);}
        void OnDestroy(){if(receiver!=null)receiver.onHit.RemoveListener(Hit);if(zones!=null)foreach(var z in zones)z.Dispose();foreach(var s in shots)s.shape.Dispose();ClearSpear();if(spear!=null)Dispose(spear.gameObject);if(fires!=null)foreach(var f in fires)if(f!=null)Dispose(f.gameObject);Dispose(material);}
